WITH kept AS (SELECT s.* FROM departments s WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.salary BETWEEN 64000 AND 112000)) SELECT CASE WHEN budget >= 4063000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, SUM(budget) FILTER (WHERE location = 'Bangkok') AS bangkok_total_budget, MIN(budget) AS min_budget, APPROX_PERCENTILE(budget, 0.9) AS budget_p90, STDDEV_SAMP(budget) AS budget_stddev FROM kept GROUP BY budget_tier;
